#![allow(unused)]
verus! {

    /// The mathematical definition of “n is prime” for 8-bit signed n.
    spec fn is_prime_def(n: i8) -> bool {
        // n must be at least 2, and there is no divisor k in [2, n).
        2 <= n
            && forall |k: i8| (2 <= k && k < n) ==> (n % k != 0)
    }

    /// Returns true if and only if n is prime (per is_prime_def).
    fn is_prime(n: i8) -> (result: bool)
        ensures
            // The Boolean result exactly matches the mathematical definition.
            result == is_prime_def(n)
    {
        // Quick reject all n < 2
        if n < 2 {
            return false;
        }

        // We will search for a divisor k in [2, n).
        let mut k: i8 = 2;

        // Loop until k == n; if we find any k dividing n, we return false immediately.
        while k < n
            invariant
                // n is known to be at least 2 throughout
                2 <= n,
            invariant
                // k always stays in the closed interval [2, n]
                2 <= k && k <= n,
            invariant
                // All smaller candidates j in [2, k) have been shown *not* to divide n.
                forall |j: i8| (2 <= j && j < k) ==> (n % j != 0),
            decreases
                // A well‐founded measure that strictly decreases each iteration:
                // here (n as int − k as int) starts ≥ 0 and shrinks on each iteration.
                (n as int - k as int)
        {
            // If k divides n, we know n is composite.
            if n % k == 0 {
                return false;
            }
            k += 1;
        }

        // If we exit the loop without finding any divisor in [2, n), n is prime.
        result = true;
    }
}